"""Build EDA and experiment reports from verified numeric results."""
from __future__ import annotations
import json
from pathlib import Path
import numpy as np,pandas as pd
ROOT=Path(__file__).resolve().parents[1]

def image(name,caption):return f'![{caption}](../results/figures/{name}.png)\n\n{caption}\n'

def main():
    from report_documentation import retain_frozen_english_reports
    if retain_frozen_english_reports(ROOT,['docs/eda_report.md','docs/experiment_report.md']):
        return
    eda=ROOT/'results/tables/eda';models=ROOT/'results/tables/models'
    monthly=pd.read_csv(eda/'monthly_purchases.csv')
    country=pd.read_csv(eda/'country_purchases.csv')
    products=pd.read_csv(eda/'train_product_popularity.csv',dtype={'StockCode':'string'})
    invoice=pd.read_csv(eda/'invoice_value_summary.csv')
    concentration=pd.read_csv(eda/'train_purchase_concentration.csv')
    rfm=pd.read_csv(ROOT/'data/processed/rfm_train.csv')
    transform=json.loads((ROOT/'data/processed/rfm_transform.json').read_text())
    top10=float(np.sort(rfm['Monetary'].to_numpy())[-int(np.ceil(.1*len(rfm))):].sum()/rfm['Monetary'].sum())
    lines=['# EDA — Hành vi mua hàng và RFM','','Dữ liệu đã qua policy 1.0. Các hình toàn kỳ là mô tả lịch sử, không dùng kết quả mô hình test để chọn tham số. RFM, sản phẩm phổ biến và ma trận tương quan chỉ lấy từ train.','','## 1. Quy mô, thời gian và giá trị đơn','',image('01_monthly_purchases','Hình 1. Số hóa đơn và giá trị mua hàng hóa theo tháng, trước hoàn trả.'),'Tháng 12/2011 chỉ đến ngày 09/12 nên không so tổng tháng này như một tháng đầy đủ. Các tổng tiền không phải lợi nhuận hoặc doanh thu ròng.','','| Cohort | Hóa đơn | Median GBP | P95 GBP | P99 GBP | Max GBP |','|---|---:|---:|---:|---:|---:|']
    for row in invoice.itertuples():lines.append(f'| {row.cohort} | {row.invoices:,} | {row.median_gbp:,.2f} | {row.p95_gbp:,.2f} | {row.p99_gbp:,.2f} | {row.max_gbp:,.2f} |')
    lines += ['',image('14_invoice_value_distribution','Hình 2. Phân phối log1p giá trị hóa đơn; giữ toàn bộ đuôi phân phối.'),'Giá trị và Quantity lớn là dấu hiệu cần xem xét, chưa đủ xác định khách mua sỉ. Các đối ứng hoàn trả ở giao dịch lớn đã được ghi trong báo cáo chuẩn bị dữ liệu.','','## 2. Giỏ hàng, sản phẩm và quốc gia','',image('03_basket_size_distribution','Hình 3. Số sản phẩm khác nhau mỗi giỏ; giỏ một sản phẩm vẫn nằm trong mẫu số support.'),image('02_train_top_products','Hình 4. Sản phẩm xuất hiện ở nhiều hóa đơn train nhất; không dùng tổng Quantity thay cho độ phổ biến.'),'| StockCode | Tên hiển thị train | Hóa đơn train | Tỷ lệ hóa đơn |','|---|---|---:|---:|']
    for row in products.head(5).itertuples():lines.append(f'| {row.StockCode} | {row.DisplayName.strip()} | {row.invoice_count:,} | {row.invoice_prevalence:.2%} |')
    leader=country.iloc[0]
    lines += ['',image('04_country_concentration','Hình 5. Mức tập trung hóa đơn theo quốc gia.'),f"{leader['Country']} chiếm {leader['invoice_fraction']:.2%} hóa đơn hàng hóa hợp lệ. Giữ mọi quốc gia nhưng kết quả chịu ảnh hưởng lớn từ thị trường này; không suy rộng tự động sang thương mại điện tử Việt Nam.",'','## 3. RFM train và mức tập trung giá trị','',image('05_train_rfm_distributions','Hình 6. RFM gốc và sau log1p trên cùng 3.145 khách train.'),f"Skewness trước biến đổi: Recency {transform['raw_train_skewness']['Recency']:.3f}, Frequency {transform['raw_train_skewness']['Frequency']:.3f}, Monetary {transform['raw_train_skewness']['Monetary']:.3f}. Frequency và Monetary lệch phải mạnh; log1p/chuẩn hóa giảm ưu thế thang đo, không thay việc kiểm tra ý nghĩa giao dịch.",'',image('06_train_purchase_concentration','Hình 7. Mức tập trung giá trị mua gộp ở khách train.'),f'Top 10% khách train đóng góp khoảng {top10:.2%} giá trị mua hàng hóa trước hoàn trả. Đây là mức tập trung mua gộp, không chứng minh phân bổ lợi nhuận.','',image('07_train_rfm_correlations','Hình 8. Tương quan giữa các đặc trưng log-z train.'),'Frequency và Monetary cùng phản ánh một phần mức độ hoạt động mua; tương quan không chứng minh quan hệ nhân quả. RFM không có nhãn churn thật và không được dùng để gọi khách có Recency lớn là đã rời bỏ.','','## 4. Hệ quả cho thực nghiệm','','- Association rules dùng sự hiện diện trong hóa đơn, giữ mẫu số mọi giỏ; không để đơn mua số lượng lớn tăng support nhiều lần.','- K-means dùng ba đặc trưng log-z đã fit train; số cụm phải dựa trên độ phân tách, ổn định, quy mô và diễn giải.','- Chia theo thời gian và giữ nguyên hóa đơn; vocabulary và tên sản phẩm chỉ từ train.','- Khách mới/thiếu ID và sản phẩm mới phải được báo cáo, không bỏ khỏi đánh giá để tăng chỉ số.','','Các bảng số liệu gốc nằm trong results/tables/eda. Các hình có cả PNG và SVG để chèn báo cáo/slide.']
    (ROOT/'docs/eda_report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')

    rules=json.loads((models/'selected_rule_config.json').read_text())
    clusters=json.loads((ROOT/'results/models/selected_kmeans_metadata.json').read_text())
    comparison=pd.read_csv(models/'segment_vs_global_validation.csv')
    cohort=json.loads((models/'segment_comparison_metadata.json').read_text())
    profiles=pd.read_csv(models/'cluster_profiles.csv')
    ks=pd.read_csv(models/'clustering_k_comparison.csv')
    paired_checks=pd.read_csv(models/'paired_algorithm_checks.csv')
    paired_runtime=pd.read_csv(eda/'paired_subset_runtime_summary.csv')
    full_benchmark=pd.read_csv(ROOT/'results/experiments/global_rules/benchmark_status.csv')
    examples=pd.read_csv(models/'selected_global_rules.csv',dtype={'antecedent':'string','consequent':'string'})
    segment_summary=pd.read_csv(models/'segment_rule_summary.csv')
    selected_k=clusters['selected_k_metrics']
    lines=['# Thực nghiệm luật kết hợp và phân khúc khách hàng','','## 1. Thiết kế và môi trường','','- Backend thực chạy: Weka 3.8.7 thông qua Java bridge trong src/WekaExperimentBridge.java. Python/pandas/numpy kiểm tra số đếm, tính metric và tạo bảng; ReportLab/Sharp tạo 15 hình SVG/PNG. Không giả định đã cài scikit-learn/mlxtend.','- Train có 11.044 giỏ, vocabulary 3.564 sản phẩm; RFM có 3.145 khách. Validation từ 01/08 đến trước 01/10/2011. Test từ 01/10 đến trước 10/12/2011 chưa được chấm điểm.','- Quality audit đã xem cấu trúc/bất thường toàn kỳ; không gọi test là dữ liệu chưa từng được xem dưới mọi hình thức. Không khai phá luật hoặc chọn K bằng dữ liệu test.','- Protocol và tiêu chí chọn ghi trong configs/experiment_protocol.json; trường hợp thiếu tài nguyên được ghi thành timeout và chuyển sang so sánh trên cùng mẫu train.','','## 2. Apriori và FP-Growth: kiểm chứng và tài nguyên','','Dữ liệu Weka biểu diễn hai giá trị absent/present; Apriori đặt treatZeroAsMissing=true, FP-Growth chọn present. Chỉ khai phá sự hiện diện. Giữ mọi hóa đơn, gồm cả giỏ không có sản phẩm đủ ngưỡng. Các singleton dưới ngưỡng được lược khỏi đặc trưng đầu vào bằng cùng quy tắc cho hai thuật toán.','','Weka Apriori làm tròn support×N còn FP-Growth lấy ceil. Project dùng ngưỡng đếm yêu cầu ceil(requested_support×N), đặt fraction nội bộ (count−0.25)/N và kiểm tra lại số đếm. Hai thuật toán khai phá không giới hạn độ dài để benchmark cùng điều kiện, rồi báo cáo các luật chứa tối đa ba item. Đây không phải benchmark Apriori bounded-max-len=3.','','| Support yêu cầu | Count tối thiểu train | FP rules báo cáo ≤3 item | Apriori toàn train |','|---|---:|---:|---|']
    checks=pd.read_csv(models/'association_algorithm_checks.csv')
    for row in checks.itertuples():lines.append(f"| {row.requested_support:.0%} | {row.minimum_count} | {row.fp_reported_max3_rules:,} | {'Hoàn tất; trùng luật và count' if row.apriori_completed else 'Không hoàn tất trong 45 giây wall/lượt; không dùng kết quả dở'} |")
    lines += ['','Các lượt FP-Growth hoàn tất ba lần mỗi ngưỡng. Apriori hoàn tất ba lần ở 5%; tại 1% và 2% dừng sau một timeout, không bịa thời gian hoàn tất. Giới hạn 45 giây tính cả khởi động/đọc input của lượt chạy; thời gian thành công trong bảng benchmark đo fit + sinh luật, không đo riêng hai phần hoặc bộ nhớ.','','Để so sánh không rỗng, dùng cùng mẫu 500 hóa đơn train, lấy không hoàn lại bằng seed 42, giữ danh sách chỉ số. So sánh ba lần, đổi thứ tự thuật toán giữa các lần:','','| Support trên mẫu | Luật ≤3 item mỗi thuật toán | Count và tập luật | Apriori median ms | FP-Growth median ms |','|---|---:|---|---:|---:|']
    for row in paired_checks.itertuples():
        subset=paired_runtime.loc[paired_runtime['requested_support'].eq(row.support)].set_index('algorithm')
        lines.append(f"| {row.support:.0%} | {row.rules_max3:,} | Giống nhau; count kiểm tra độc lập | {subset.loc['apriori','median']:,.2f} | {subset.loc['fpgrowth','median']:,.2f} |")
    lines += ['',image('15_paired_subset_runtime','Hình 9. Benchmark trên cùng mẫu 500 giỏ; thời gian phụ thuộc implementation, máy và hoạt động hệ thống.'),'Các kiểm tra số đếm dùng bitset Python độc lập, không chỉ so hai phần mềm cùng trả một con số. Bộ kiểm tra nhỏ năm hóa đơn cũng cho bốn luật giống nhau. Không kết luận Apriori luôn chậm hơn FP-Growth ở mọi dataset.','','## 3. Chọn cấu hình luật bằng validation','','Grid gồm support 1%/2%/5%, độ dài luật báo cáo 2/3 và confidence 0.3/0.5/0.7; yêu cầu lift≥1.1, count≥20, consequent một sản phẩm. Có 18 cấu hình. Xếp hạng theo HitRate@5 validation, hòa thì ít luật hơn, ngắn hơn, support cao hơn, confidence cao hơn.','','Bài toán đánh giá là hoàn thiện giỏ hàng ngoại tuyến: với hóa đơn có ít nhất hai sản phẩm khác nhau, ẩn một sản phẩm bằng hash cố định của invoice/seed. Sản phẩm ẩn có thể chưa từng xuất hiện ở train. Gợi ý chỉ từ train, loại các sản phẩm đã nhìn thấy; cả mô hình và baseline dùng cùng cách điền sản phẩm phổ biến khi không đủ năm gợi ý. Không diễn giải đây là dự đoán thứ tự click hoặc tăng doanh thu thực tế.','',f"Có {int(rules['eligible_baskets']):,} giỏ validation đủ điều kiện; {rules['hidden_targets_outside_train_vocabulary']} target ngoài vocabulary train vẫn nằm trong mẫu số. Với một target ẩn, HitRate@5 và Recall@5 trùng giá trị nên không tính là hai bằng chứng độc lập.",'','| Cấu hình được chọn | Giá trị |','|---|---:|',f"| Min support | {rules['min_support']:.0%} |",f"| Max tổng item trong luật | {int(rules['max_len'])} |",f"| Min confidence | {rules['min_confidence']:.1f} |",f"| Số luật | {int(rules['rule_count']):,} |",f"| HitRate@5 | {int(rules['hits'])}/{int(rules['eligible_baskets'])} = {rules['hit_rate_at_5']:.2%} |",f"| Baseline popularity | {rules['baseline_popularity']['hits']}/{rules['baseline_popularity']['eligible_baskets']} = {rules['baseline_popularity']['hit_rate_at_5']:.2%} |",f"| Có ít nhất một gợi ý từ luật | {rules['rule_coverage']:.2%} |",'',image('12_validation_rule_selection','Hình 10. Các cấu hình dẫn đầu trên validation và baseline.'),'Đây là kết quả của tập dùng chọn cấu hình, có thể lạc quan. Chưa có kết luận về hiệu năng final test hoặc cải thiện bán hàng.','','### Ví dụ luật có nhiều bằng chứng','','| Luật theo StockCode | Count train | Support | Confidence train | Lift train | Count validation | Confidence validation |','|---|---:|---:|---:|---:|---:|---:|']
    seen=set();shown=0
    for row in examples.itertuples():
        key=tuple(sorted([row.antecedent,row.consequent]))
        if key in seen:continue
        seen.add(key)
        lines.append(f'| {row.antecedent} → {row.consequent} | {row.count_ab} | {row.support:.2%} | {row.confidence:.2%} | {row.lift:.2f} | {row.validation_count_ab} | {row.validation_confidence:.2%} |')
        shown+=1
        if shown==5:break
    first=examples.iloc[0]
    lines += ['', 'Support(A→B)=count(A∪B)/N; confidence(A→B)=count(A∪B)/count(A); lift(A→B)=confidence(A→B)/(count(B)/N). Ví dụ kiểm tra tay trên 5 giỏ: A có ở 4 giỏ, B có ở 3 giỏ, cùng A/B có ở 2 giỏ. Support=2/5=0,4; confidence=2/4=0,5; lift=0,5/(3/5)=0,8333. Đây là fixture kiểm chứng công thức, không phải kết quả dataset.']
    lines += ['',f"Ví dụ đầu: {first['antecedent_names'].strip()} → {first['consequent_names'].strip()}. Luật mô tả đồng xuất hiện, không chứng minh mua sản phẩm đầu gây ra việc mua sản phẩm sau.",'','## 4. K-means trên RFM train','','Dùng ba đặc trưng log1p/chuẩn hóa đã fit trước đó. Weka K-means++ chạy K=2…8, năm nhóm seed 42…46, mỗi nhóm giữ nghiệm SSE thấp nhất trong 20 khởi tạo; tối đa 300 vòng, một execution slot. Tắt chuẩn hóa khoảng cách bên trong Weka để không chuẩn hóa lần hai. Tổng cộng 700 lần khởi tạo.','','Silhouette Euclidean tính trên toàn bộ 3.145 khách train. Kiểm tra SSE độc lập từ centroid/assignment. Độ ổn định là ARI trung bình giữa các cặp nhóm seed; không so trực tiếp số nhãn cụm. K hợp lệ cần cụm nhỏ nhất≥3% khách và ARI trung bình≥0.8; chọn mean silhouette cao nhất, trong 0.005 thì ưu tiên K nhỏ.','','| K | Mean silhouette | Mean SSE | Mean ARI | Tỷ lệ cụm nhỏ nhất qua seed |','|---|---:|---:|---:|---:|']
    for row in ks.itertuples():lines.append(f'| {row.k} | {row.mean_silhouette:.4f} | {row.mean_sse:,.2f} | {row.mean_pairwise_ARI:.4f} | {row.minimum_cluster_fraction_across_seeds:.2%} |')
    lines += ['',f"Chọn **K={clusters['k']}**. Mean silhouette={selected_k['mean_silhouette']:.4f}, ARI={selected_k['mean_pairwise_ARI']:.4f}. Đây là tiêu chí nội bộ và tính diễn giải, không phải accuracy với nhãn phân khúc thật.",'',image('08_k_selection','Hình 11. SSE giảm khi tăng K nhưng silhouette không tăng tương ứng.'),image('09_train_cluster_projection','Hình 12. PCA chỉ để minh họa; mô hình vẫn dùng đủ ba đặc trưng.'),'','| Segment | Khách | Median R, ngày | Median F, hóa đơn | Median M, GBP | Tỷ trọng giá trị mua gộp train |','|---|---:|---:|---:|---:|---:|']
    for row in profiles.itertuples():lines.append(f'| {row.Segment} | {row.customers:,} | {row.median_recency:.0f} | {row.median_frequency:.0f} | {row.median_monetary:,.2f} | {row.gross_purchase_value_fraction:.2%} |')
    lines += ['',image('10_segment_profiles','Hình 13. Hồ sơ cụm trong đơn vị RFM gốc.'),'Segment_1 mua gần đây hơn, thường xuyên hơn và giá trị mua gộp cao hơn; Segment_2 có đặc điểm ngược lại so với trung vị chung. Không gọi Segment_2 là churn đã xác minh, không gọi Segment_1 là sinh lợi, vì Monetary chưa trừ hoàn trả/chi phí.','','## 5. Liên kết phân khúc và luật kết hợp','','Mô hình phân khúc giữ nguyên hồ sơ trước cutoff, không tái tạo RFM bằng dữ liệu tương lai. Khai phá luật global và theo segment trên cùng cohort khách có hồ sơ train, dùng lại tham số luật đã chọn. Các nhóm dùng threshold count=max(ceil(support×N_nhóm),20), vì vậy support tương đối có thể được nâng lên khi nhóm nhỏ.','','| Nhóm khai phá | Giỏ train | Giỏ validation | Luật giữ lại | Count tối thiểu |','|---|---:|---:|---:|---:|']
    for row in segment_summary.itertuples():lines.append(f'| {row.group} | {row.train_baskets:,} | {row.validation_baskets:,} | {row.selected_rules:,} | {row.minimum_count} |')
    lines += ['',f"So sánh dùng {cohort['eligible_masked_validation_baskets']:,} giỏ validation cùng cohort; {cohort['validation_baskets_outside_cohort']} hóa đơn khách mới/không có hồ sơ được báo riêng, không gán phân khúc giả. Không so trực tiếp các tỷ lệ ở bảng này với 13,76% ở mục 3 vì cohort khác nhau.",'','| Phương án | HitRate@5 | Hits / giỏ | Coverage từ luật |','|---|---:|---:|---:|']
    for row in comparison.itertuples():lines.append(f'| {row.method} | {row.hit_rate_at_5:.2%} | {row.hits}/{row.eligible_baskets} | {row.rule_coverage:.2%} |')
    lines += ['',image('13_segment_rule_comparison','Hình 14. So sánh ba phương án trên cùng giỏ, target và fallback.'),'**Luật theo phân khúc chưa vượt luật toàn cục trên cohort hiện tại.** Phân khúc có giá trị mô tả hành vi, nhưng chia nhỏ dữ liệu không tự bảo đảm cải thiện gợi ý. Đây là kết quả cần trình bày trung thực; không đổi seed/K để ép kết quả thuận lợi. Chưa kiểm tra ý nghĩa thống kê hoặc final test cho chênh lệch nhỏ này.','','## 6. Đầu ra và tái tạo','','- 15 hình PNG/SVG và bảng EDA trong results/figures, results/tables/eda.','- Grid luật, rule stability, hồ sơ cụm và so sánh segment trong results/tables/models.','- Model Weka và metadata mapping/centroid ở results/models; input ARFF chỉ có ba feature, không có CustomerID như biến phân cụm.','- Các log và timeout nằm trong results/experiments; experiment_manifest.json ghi hash raw/processed/protocol/artifacts.','- Chạy `& .\\scripts\\run_models.ps1` để tái tạo. Có thể đặt JAVA_EXE và WEKA_JAR khi đường dẫn cài đặt khác. Cần JDK có javac, Weka, Python có numpy/pandas/reportlab/Pillow và Node/Sharp; không phải chờ cài scikit-learn/mlxtend.','','## 7. Giới hạn và phần còn lại','','Kết quả validation được dùng cho chọn cấu hình nên chưa phải ước lượng cuối không thiên lệch. Chỉ một retailer lịch sử; giỏ ẩn item không phải hành vi click thật; gross purchases có thể bao gồm giao dịch đã hoàn trả; cụm có thể phản ánh continuum hành vi. Timings là đo cục bộ, không tách mining khỏi sinh luật và chưa đo memory đáng tin cậy. Chưa chạy final test, A/B test hoặc đo tăng doanh thu.','','Bước tiếp theo phù hợp là khóa cấu hình hiện tại, chạy một lần đánh giá final test theo protocol, rồi hoàn thiện báo cáo/slide. Nếu sửa phương pháp từ kết quả test, phải ghi rõ và không tiếp tục gọi cùng test là độc lập.','','## Nguồn kỹ thuật','','- Weka SimpleKMeans: https://weka.sourceforge.io/doc.stable/weka/clusterers/SimpleKMeans.html','- Weka FPGrowth: https://weka.sourceforge.io/doc.stable/weka/associations/FPGrowth.html','- Cách định nghĩa silhouette tham khảo: https://scikit-learn.org/stable/modules/generated/sklearn.metrics.silhouette_score.html','- Công thức support/confidence/lift: https://rasbt.github.io/mlxtend/user_guide/frequent_patterns/association_rules/','- UCI Online Retail: https://doi.org/10.24432/C5BW33. Source dataset đã trích dẫn trong proposal/raw audit.']
    (ROOT/'docs/experiment_report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    final_scored=(ROOT/'results/tables/final_test/evaluation_receipt.json').exists()
    if final_scored:
        path=ROOT/'docs/experiment_report.md'
        content=path.read_text(encoding='utf-8')
        heading,rest=content.split('\n',1)
        notice='\n\n> Phạm vi: kết quả train/validation tại thời điểm chọn cấu hình. Final test đã hoàn tất với mô hình khóa; xem [báo cáo final test](final_evaluation_report.md) và [báo cáo tổng hợp](../report/project_report.md). Các câu về trạng thái chưa chấm test bên dưới mô tả mốc trước final test.\n'
        path.write_text(heading+notice+rest,encoding='utf-8')
    print(json.dumps({'reports':['docs/eda_report.md','docs/experiment_report.md'],'final_test_scored':final_scored}))

